const b=document.querySelector('.menu-toggle'),m=document.querySelector('#site-menu');if(b&&m){b.addEventListener('click',()=>{const o=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!o));m.classList.toggle('open',!o)});m.addEventListener('click',e=>{if(e.target.tagName==='A'){b.setAttribute('aria-expanded','false');m.classList.remove('open')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){b.setAttribute('aria-expanded','false');m.classList.remove('open');b.focus()}})}